    }
    if !self.homeLabel.isEmpty {
      try visitor.visitSingularStringField(value: self.homeLabel, fieldNumber: 9)
    }
    try unknownFields.traverse(visitor: &visitor)
  }

  public static func ==(lhs: Cadpole_V1_PublishedView, rhs: Cadpole_V1_PublishedView) -> Bool {
    if lhs.camera != rhs.camera {return false}
